reference_solution:
def is_valid_tree_preorder(nodes):
    stack=[]
    for node,parent in nodes:
        if parent==-1:
            if stack:return False
            stack=[node];continue
        while stack and stack[-1]!=parent:stack.pop()
        if not stack:return False
        stack.append(node)
    return bool(stack)

